package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
)

// Only fields generated by the sanitized J2534 proxy are read. CAN payloads
// are not part of schema15 and are never parsed or saved here.
type CoreBridgeAssessment struct {
	Enabled                  bool           `json:"enabled"`
	Version                  int            `json:"version"`
	InspectedD2TX            int            `json:"inspected_d2_tx"`
	Classes                  map[string]int `json:"classes"`
	RouteMismatchAnnotations int            `json:"route_mismatch_annotations"`
	B9FBDelegated            int            `json:"b9fb_delegated"`
	A3NeedsEvidence          int            `json:"a3_needs_evidence"`
	B9F0NeedsEvidence        int            `json:"b9f0_needs_evidence"`
	Note                     string         `json:"note"`
}

func readCoreBridgeAssessment(raw []byte) (CoreBridgeAssessment, error) {
	r := CoreBridgeAssessment{
		Classes: map[string]int{},
		Note:    "Categories are from TX messages accepted by the J2534 driver. No ECU reply validation, ignition state, security access or synthesized responses. Route mismatches are annotations only; B9FB remains delegated to the original driver.",
	}
	sc := bufio.NewScanner(bytes.NewReader(raw))
	sc.Buffer(make([]byte, 4096), 1024*1024)
	for sc.Scan() {
		var e struct {
			Schema       int    `json:"schema"`
			CoreVersion  int    `json:"core_version"`
			Event        string `json:"event"`
			Status       uint32 `json:"status"`
			Count        uint32 `json:"count"`
			CoreClass    string `json:"core_class"`
			CoreDecision uint32 `json:"core_decision"`
		}
		if err := json.Unmarshal(sc.Bytes(), &e); err != nil {
			return r, fmt.Errorf("core bridge JSONL: %w", err)
		}
		if e.Schema != 15 || e.CoreVersion != 26 {
			continue
		}
		r.Enabled = true
		r.Version = 26
		if e.Event != "write" || e.Status != 0 || e.Count == 0 || e.CoreClass == "" {
			continue
		}
		switch e.CoreClass {
		case "a3_0203_shape", "a3_other", "b9e0", "b9f0", "b9fb_existing", "b9fc", "a6_ref6660_candidate", "unknown", "invalid_request":
		default:
			return r, fmt.Errorf("invalid core classification: %q", e.CoreClass)
		}
		r.InspectedD2TX++
		r.Classes[e.CoreClass]++
		if e.CoreDecision == 1 {
			r.RouteMismatchAnnotations++
		}
		if e.CoreClass == "b9fb_existing" && e.CoreDecision == 0 {
			r.B9FBDelegated++
		}
		if e.CoreClass == "a3_0203_shape" && e.CoreDecision == 2 {
			r.A3NeedsEvidence++
		}
		if e.CoreClass == "b9f0" && e.CoreDecision == 2 {
			r.B9F0NeedsEvidence++
		}
	}
	if err := sc.Err(); err != nil {
		return r, err
	}
	return r, nil
}
